//! Additional social post surfaces, painted by the same Rust display-list engine.
use crate::{color::Rgba,display::{DisplayList,Item,ImageRef,Rect,Shape},inline::{self,Span,BlockStyle,Wrap,Dir},model::{self,Post,RenderOptions,Theme,Verified}};
fn text(s:&str,w:f32,size:f32,weight:u16,color:Rgba)->inline::TextBlock{inline::layout(&[Span::new(s,color,weight)],&BlockStyle{size,line_height:size*1.4,weight,width:w.max(1.0),max_lines:None,wrap:Wrap::Anywhere,preserve:true,dir:Dir::Auto,tab_size:4.0})}
fn label(l:&mut DisplayList,s:&str,x:f32,y:f32,w:f32,size:f32,weight:u16,c:Rgba)->f32{let t=text(s,w,size,weight,c);let h=t.height;l.push_text(&t,x,y);h}
fn icon(l:&mut DisplayList,n:&str,x:f32,y:f32,size:f32,c:Rgba){l.items.push(Item::Icon{name:n.into(),rect:Rect::new(x,y,size,size),color:c})}
fn avatar(l:&mut DisplayList,p:&Post,x:f32,y:f32,size:f32,line:Rgba,fg:Rgba){let shape=Shape::rounded(Rect::new(x,y,size,size),size/2.0);if p.author.avatar.is_some(){l.items.push(Item::Image{shape,image:ImageRef::Avatar,focus:(0.5,0.5)})}else{l.items.push(Item::Fill{shape,color:line});label(l,&p.author.handle.chars().next().unwrap_or('•').to_uppercase().to_string(),x+size*0.3,y+size*0.16,size,16.0,700,fg);}}
fn paragraphs(l:&mut DisplayList,s:&str,x:f32,mut y:f32,w:f32,size:f32,c:Rgba)->f32{for(i,p)in s.split("\n\n").enumerate(){if i>0{y+=10.0}y+=label(l,p.trim_end(),x,y,w,size,400,c);}y}
fn media(l:&mut DisplayList,p:&Post,x:f32,y:f32,w:f32,max:f32,r:f32)->f32{if let Some(m)=p.media.first(){let h=(w*m.height.max(1)as f32/m.width.max(1)as f32).clamp(100.0,max);let shape=Shape::rounded(Rect::new(x,y,w,h),r);if m.data.is_some(){l.items.push(Item::Image{shape,image:ImageRef::Media(0),focus:(0.5,0.5)})}else{l.items.push(Item::Placeholder{shape,label:"Media preview unavailable".into()})}if p.media.len()>1{l.items.push(Item::Fill{shape:Shape::rounded(Rect::new(x+w-52.0,y+12.0,40.0,24.0),12.0),color:Rgba::rgba(0,0,0,160)});label(l,&format!("1/{}",p.media.len()),x+w-43.0,y+16.0,36.0,11.0,400,Rgba::WHITE);}h}else{0.0}}
fn report(p:&Post,l:&DisplayList)->model::Report{let mut r=model::Report::default();r.ruleset=format!("xeet-{}-v1",p.platform);r.size=model::Size{width:l.width,height:l.height};r.text=model::TextReport{visible:p.text.clone(),..Default::default()};let limit=match p.platform.as_str(){"instagram"=>2200,"facebook"=>63206,_=>4000};r.length=model::Length{weighted:p.text.chars().count()as u32,limit,valid:p.text.chars().count()<=limit as usize};r.warnings.push("Platform-specific Rust preview with open Noto fonts; not pixel-parity certified. Videos render as stills.".into());if p.media.len()>1{r.warnings.push("The first carousel item is shown with its item count.".into());}r}
pub fn layout(p:&Post,o:&RenderOptions)->(DisplayList,model::Report){if p.platform=="tiktok"{return tiktok(p,o)}let ig=p.platform=="instagram";let dark=o.theme==Theme::Dark;let bg=if dark{Rgba::rgb(16,16,16)}else{Rgba::WHITE};let fg=if dark{Rgba::rgb(245,245,245)}else{Rgba::rgb(20,20,20)};let muted=if dark{Rgba::rgb(170,170,170)}else{Rgba::rgb(110,110,110)};let line=if dark{Rgba::rgb(48,48,48)}else{Rgba::rgb(220,220,220)};let w=o.width.clamp(200.0,1200.0);let mut l=DisplayList::new(w,0.0,Rgba::TRANSPARENT);let pad=16.0;avatar(&mut l,p,pad,16.0,if ig{32.0}else{40.0},line,fg);let name=if ig||p.author.name.is_empty(){p.author.handle.trim_start_matches('@')}else{&p.author.name};let x=if ig{58.0}else{66.0};let h=crate::frame::header::one_line(name,fg,700,crate::tokens::TypeStyle{size:15.0,line_height:21.0},Wrap::Anywhere,false,w-x-42.0);l.push_text(&h,x,if ig{22.0}else{14.0});if p.author.verified!=Verified::None{icon(&mut l,"teet-verified",(x+h.width+5.0).min(w-42.0),if ig{26.0}else{18.0},13.0,Rgba::rgb(0,149,246));}let time=if p.created_at.is_some(){crate::frame::time::label(p.created_at.as_deref(),p.now.as_deref(),false)}else{String::new()};if !ig{label(&mut l,&time,x,35.0,w-x-30.0,12.0,400,muted);}icon(&mut l,"teet-more",w-36.0,23.0,20.0,muted);let mut y=if ig{64.0}else{68.0};let counts=p.counts.clone().unwrap_or_default();
 if !ig{y=paragraphs(&mut l,&p.text,pad,y,w-2.0*pad,15.0*o.font_scale,fg);y+=12.0;}
 let mh=media(&mut l,p,1.0,y,w-2.0,w*1.25,0.0);if mh>0.0{y+=mh+12.0;}
 if ig{for(i,n)in["teet-like","teet-reply","teet-share"].iter().enumerate(){icon(&mut l,n,pad+i as f32*36.0,y,23.0,fg)}icon(&mut l,"social-bookmark",w-39.0,y,23.0,fg);y+=34.0;if counts.likes>0{y+=label(&mut l,&format!("{} likes",crate::frame::numbers::compact(counts.likes)),pad,y,w-32.0,14.0,700,fg)+5.0;}let caption=format!("{}  {}",p.author.handle.trim_start_matches('@'),p.text);y=paragraphs(&mut l,&caption,pad,y,w-32.0,14.0*o.font_scale,fg);if counts.replies>0{y+=8.0;y+=label(&mut l,&format!("View all {} comments",counts.replies),pad,y,w-32.0,13.0,400,muted);}if !time.is_empty(){y+=8.0;y+=label(&mut l,&time,pad,y,w-32.0,11.0,400,muted);}y+=18.0;}else{if counts.likes>0{icon(&mut l,"social-like",pad,y,17.0,Rgba::rgb(8,102,255));label(&mut l,&crate::frame::numbers::compact(counts.likes),pad+23.0,y,w*0.4,13.0,400,muted);}let mut metrics=Vec::new();if counts.replies>0{metrics.push(format!("{} comments",crate::frame::numbers::compact(counts.replies)));}if counts.reposts>0{metrics.push(format!("{} shares",crate::frame::numbers::compact(counts.reposts)));}let m=metrics.join(" · ");let tw=text(&m,w-90.0,12.0,400,muted);l.push_text(&tw,(w-pad-tw.width).max(80.0),y);y+=26.0;l.items.push(Item::Fill{shape:Shape::rounded(Rect::new(pad,y,w-32.0,1.0),0.0),color:line});y+=12.0;for(i,(n,t))in[("social-like","Like"),("teet-reply","Comment"),("social-share","Share")].iter().enumerate(){let cell=(w-32.0)/3.0;let xx=pad+i as f32*cell+4.0;icon(&mut l,n,xx,y,18.0,muted);label(&mut l,t,xx+24.0,y,cell-28.0,12.0,700,muted);}y+=34.0;}
 l.height=y;let card=Shape::rounded(Rect::new(0.5,0.5,w-1.0,y-1.0),if ig{3.0}else{10.0});l.items.insert(0,Item::Fill{shape:card,color:bg});l.items.push(Item::Stroke{shape:card,color:line,width:1.0});let r=report(p,&l);(l,r)}
fn tiktok(p:&Post,o:&RenderOptions)->(DisplayList,model::Report){let w=o.width.clamp(200.0,640.0);let h=w*16.0/9.0;let mut l=DisplayList::new(w,h,Rgba::BLACK);let shape=Shape::rounded(Rect::new(0.0,0.0,w,h),0.0);if p.media.first().is_some_and(|m|m.data.is_some()){l.items.push(Item::Image{shape,image:ImageRef::Media(0),focus:(0.5,0.5)})}else{l.items.push(Item::Placeholder{shape,label:"Video preview unavailable".into()})}for i in 0..220{let yy=(h-220.0).floor()+i as f32;l.items.push(Item::Fill{shape:Shape::rounded(Rect::new(0.0,yy,w,1.0),0.0),color:Rgba::rgba(0,0,0,(i as f32/220.0*200.0)as u8)});}let right=w-48.0;avatar(&mut l,p,right,h-320.0,36.0,Rgba::rgb(50,50,50),Rgba::WHITE);let c=p.counts.clone().unwrap_or_default();for(i,(n,count))in[("icon-heart-fill",c.likes),("teet-reply",c.replies),("social-share",c.reposts)].iter().enumerate(){let y=h-260.0+i as f32*64.0;icon(&mut l,n,right+3.0,y,30.0,Rgba::WHITE);if *count>0{label(&mut l,&crate::frame::numbers::compact(*count),right-8.0,y+34.0,60.0,12.0,700,Rgba::WHITE);}}let name=format!("@{}",p.author.handle.trim_start_matches('@'));let caption=inline::layout(&[Span::new(&p.text,Rgba::WHITE,400)],&BlockStyle{size:14.0*o.font_scale,line_height:20.0*o.font_scale,weight:400,width:w-88.0,max_lines:Some(5),wrap:Wrap::Anywhere,preserve:true,dir:Dir::Auto,tab_size:4.0});let y=h-32.0-caption.height;label(&mut l,&name,16.0,y-28.0,w-88.0,15.0,700,Rgba::WHITE);l.push_text(&caption,16.0,y);let r=report(p,&l);(l,r)}
